-- Mauritania fourth preparatory year (mapped grade 10): 43 original
-- supplementary exercises across existing official-import title stubs.
-- Independent educational prose; all ministry/source matching is pending.
DO $dadyoom$
DECLARE r RECORD; target_id uuid; prior text; nact integer; hasprogress integer;
BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset('[{"unit":"a06f37d7-0472-4ee2-8264-ad8b407c8c85","n":1,"title":"حقوق الجار","passage":"في مجتمع سكني مستقل وضع الجيران مواعيد مناسبة للهدوء وتبادلوا المساعدة عند الحاجة. يميز القارئ بين الواجب الأخلاقي والموقف المتخيل، ولا ينسب تفاصيل المثال إلى حديث ديني.","question":"ما التصرف الذي يراعي حق الجار في المثال؟","correct":"احترام الهدوء والمساعدة","wrong":["التسبب في الإزعاج","تجاهل كل طلب","الإساءة إلى الآخرين"],"practice":"اقرأ مصدرًا معتبرًا عن حق الجار، ووثق العبارة التي تستشهد بها وقارنها بمشهد من إنشائك."},{"unit":"a06f37d7-0472-4ee2-8264-ad8b407c8c85","n":2,"title":"العطف","passage":"في «حضرَ الطالبُ والمعلمُ» الواو حرف عطف يربط المعطوف بالمعطوف عليه، ويتبع المعطوف ما قبله في إعرابه وفق القاعدة. تختلف دلالة الواو عن «ثم» التي قد تفيد الترتيب مع التراخي.","question":"ما حرف العطف في «حضر الطالب والمعلم»؟","correct":"الواو","wrong":["اللام","في","إن"],"practice":"كوّن أربع جمل متنوعة بحروف عطف مختلفة، وبيّن المعطوف ومعناه."},{"unit":"a06f37d7-0472-4ee2-8264-ad8b407c8c85","n":3,"title":"حقوق المرأة في الإسلام","passage":"عند دراسة نص بعنوان حقوق المرأة ينبغي التثبت من مصادر الأحكام والنقل، والتمييز بين النص الديني الصحيح وتفسير الكاتب والسياق الاجتماعي. مثال مستقل يناقش فريق كيف يضمن تكافؤ الفرص في نشاط تعليمي، ولا ينقل فتوى أو حديثًا.","question":"ما الذي يسبق نسبة حكم ديني إلى مصدره؟","correct":"التحقق من المرجع وصحة النص","wrong":["اختراع حديث مناسب","الاكتفاء بعنوان المقال","الاعتماد على إشاعة"],"practice":"حلل حجة من مصدر تعليمي موثوق، وناقش تطبيقًا مدرسيًا مستقلًا يحترم الحقوق دون اختلاق اقتباس."},{"unit":"a06f37d7-0472-4ee2-8264-ad8b407c8c85","n":4,"title":"المصدر الصناعي","passage":"يتكون المصدر الصناعي عادةً بإضافة ياء مشددة وتاء مربوطة إلى الاسم مثل «إنسانِيّة» من «إنسان» للدلالة على معنى مجرد. نميز بين استعمال الكلمة في سياقها والمصدر الأصلي، فلا تصبح كل كلمة منتهية بالتاء المربوطة مصدرًا صناعيًا.","question":"أي كلمة مصدر صناعي في المثال؟","correct":"إنسانية","wrong":["إنسان","أناس","إنسانان"],"practice":"اكتب خمسة مصادر صناعية في جمل، وفسر العلاقة بين الاسم الأصلي والمعنى المجرد."},{"unit":"a06f37d7-0472-4ee2-8264-ad8b407c8c85","n":5,"title":"بالأخاديد رسوم وخيم","passage":"لا يصح تفسير صور نص «بالأخاديد رسوم وخيم» أو نسبة بيت من العنوان فقط. في مشهد أصلي يمر راكب بمكان به آثار خيام فيتذكر تجمعًا سابقًا؛ يمكن تحليل دلالة الأطلال والذاكرة دون الادعاء أنه من القصيدة.","question":"ما الذي يحتاجه التحليل الموثوق لهذه القصيدة؟","correct":"الأبيات الصحيحة وسياقها","wrong":["العنوان وحده","شطر مخترع","تخمين اسم الراوي"],"practice":"استخرج صورة أصلية موثقة من النص المدرسي واشرح علاقتها بالمكان والذكرى."},{"unit":"a06f37d7-0472-4ee2-8264-ad8b407c8c85","n":6,"title":"اسم الآلة","passage":"اسم الآلة يدل غالبًا على الأداة التي يقع بها الفعل، مثل «مِفتاح» لفتح الأبواب و«مِنشار» للنشر، وتوجد أوزان وصيغ سماعية وحديثة. ينبغي دراسة الاستعمال لا افتراض وزن واحد لجميع الأدوات.","question":"أي كلمة اسم آلة يستعمل للفتح؟","correct":"مفتاح","wrong":["فاتح","مفتوح","افتتاح"],"practice":"اذكر ست آلات وصنف أسماءها إلى صيغ معروفة مع استعمال كل أداة في جملة."},{"unit":"a06f37d7-0472-4ee2-8264-ad8b407c8c85","n":7,"title":"أبو حنيفة وجاره السكير","passage":"يحتاج نص يحمل اسم أبي حنيفة وحكاية جاره إلى مصدر الرواية الصحيح، ولا ينبغي اختلاق تفاصيل عن الإمام أو اقتباسات عنه. مثال مستقل: يساعد جار جاره على تجاوز ضائقة ويحفظ خصوصيته؛ التدريب يركز على الفكرة الأخلاقية فقط.","question":"ما الواجب قبل نسبة موقف إلى شخصية تاريخية؟","correct":"التحقق من الرواية ومصدرها","wrong":["اختراع الحوار","تصديق كل منشور","تغيير تفاصيل القصة"],"practice":"حدد الفكرة والسند من النص المقرر، ثم اكتب موقفًا حديثًا مستقلًا يبرز حسن الجوار."},{"unit":"a06f37d7-0472-4ee2-8264-ad8b407c8c85","n":8,"title":"التشبيه وأركانه","passage":"في «العلمُ كالنورِ في الإرشاد» العلم مشبه والنور مشبه به والكاف أداة التشبيه، ووجه الشبه الإرشاد. قد تحذف الأداة أو وجه الشبه في صور أخرى، لذلك نعتمد تركيب العبارة.","question":"ما المشبه به في «العلم كالنور»؟","correct":"النور","wrong":["العلم","الكاف","في"],"practice":"صغ تشبيهين وبين أركانهما ثم ناقش أثر كل صورة في المعنى."},{"unit":"a06f37d7-0472-4ee2-8264-ad8b407c8c85","n":9,"title":"وصية أبي بكر الشقروي","passage":"عنوان الوصية لا يجيز نسبة عباراتها أو نسبتها إلى صاحبها قبل الرجوع إلى نسخة موثقة. المثال المستقل طالب يوصي زميله بتنظيم الوقت والتحقق من المصادر، ويُدرس فيه الأمر والنهي والحجة دون اختلاق نص تراثي.","question":"ما الذي يميز النص الوصائي في المثال؟","correct":"إرشاد المخاطب إلى عمل نافع","wrong":["وصف طقس فقط","تعداد أشخاص بلا غرض","حذف المخاطب"],"practice":"اقرأ النص المقرر، واستخرج صيغة نصح موثقة ثم اكتب وصية جديدة بأسلوبك."},{"unit":"a06f37d7-0472-4ee2-8264-ad8b407c8c85","n":10,"title":"البحر الكامل","passage":"تقوم الصورة الأصلية للبحر الكامل التام على تكرار «متفاعلن» ثلاث مرات في كل شطر، وتُدرس الزحافات والعلل بمثال موثق. الكتابة العروضية تعتمد الأصوات المنطوقة، لا رسم الكلمات فقط.","question":"ما التفعيلة الأساسية للبحر الكامل؟","correct":"متفاعلن","wrong":["فعولن","فاعلاتن","مفاعلتن"],"practice":"اختر بيتًا معروف المصدر على الكامل واكتبه كتابة عروضية مع مراجعة الوزن."},{"unit":"a06f37d7-0472-4ee2-8264-ad8b407c8c85","n":11,"title":"مهارة كتابة القصاصة الصحفية","passage":"تقدّم القصاصة الصحفية معلومة أساسية وعنوانًا موجزًا وذكرًا للمصدر والزمان عند الحاجة، وتفصل الوقائع من الآراء. مثال مستقل عن افتتاح ركن للمطالعة في مدرسة دون أرقام غير موثقة.","question":"ما العنصر الذي يجعل الخبر قابلًا للتحقق؟","correct":"ذكر الحدث والمصدر بوضوح","wrong":["عنوان مثير بلا وقائع","رأي مجهول","نقل إشاعة"],"practice":"اكتب قصاصة من خمسة أسطر حول حدث مدرسي متخيل مع عنوان ووقت ومصدر افتراضي معلن."},{"unit":"ffd320bc-d285-458e-91b3-5eca91760e2c","n":1,"title":"الاستقلال","passage":"قراءة نص عن الاستقلال تستلزم تحديد المكان والتاريخ والمصدر والتمييز بين التوثيق والخطاب الاحتفالي. مثال أصلي تعرض فيه مدرسة وثائق من أرشيفها عن مناسبة وطنية، دون ادعاء تفاصيل تاريخية غير مثبتة.","question":"ما أفضل أساس لتفسير حدث تاريخي في نص؟","correct":"تاريخ موثق ومصدر واضح","wrong":["تخمين رواية","ذكر الشعار فقط","اختلاق شاهد"],"practice":"حلل فقرة تاريخية مع مصدرها وفرق بين المعلومة والوصف البلاغي."},{"unit":"ffd320bc-d285-458e-91b3-5eca91760e2c","n":2,"title":"التوكيد","passage":"في «حضرَ الطلابُ كلُّهم» «كلُّهم» توكيد معنوي يبين الشمول، وفي تكرار اللفظ المقصود توكيد لفظي. يتبع التوكيد المؤكد في إعرابه وفق القاعدة، ونفحص المعنى قبل تحديد النوع.","question":"ما نوع التوكيد في «حضر الطلاب كلهم»؟","correct":"توكيد معنوي","wrong":["نعت","حال","مفعول مطلق"],"practice":"اكتب أربع جمل لتوكيد معنوي ولفظي مع ضبط التابع والمتبوع."},{"unit":"ffd320bc-d285-458e-91b3-5eca91760e2c","n":3,"title":"الجاليات الموريتانية في الخارج","passage":"تناقش القراءة تجارب المهاجرين وروابطهم الثقافية دون تعميم تجربة شخص واحد على جميع الجاليات. في مثال مستقل تحافظ أسرة على اللغة العربية بالتواصل والقراءة مع احترام لغة بلد الإقامة.","question":"ما الطريقة التي دعمت التواصل اللغوي في المثال؟","correct":"القراءة والتواصل بالعربية","wrong":["إلغاء تعلم اللغات","إخفاء التراث","قطع الصلات"],"practice":"اكتب تقريرًا من مصادر موثوقة عن تجربة ثقافية للجاليات مع بيان تنوع السياقات."},{"unit":"ffd320bc-d285-458e-91b3-5eca91760e2c","n":4,"title":"الأحرف المشبهة بليس","passage":"من أدوات النفي التي قد تعمل عمل «ليس» في شروط نحوية معينة «ما» في بعض الاستعمالات. يحتاج التحليل إلى تحقق الشروط والضبط، فلا نعد كل «ما» ناسخة أو نجزم بإعرابها من لفظها وحده.","question":"ما الذي يحدد عمل «ما» عمل «ليس»؟","correct":"استيفاء الشروط النحوية والسياق","wrong":["وجود ما في كل جملة","طول الجملة","عدد الأفعال"],"practice":"ابحث في مرجع نحوي عن مثال صحيح لـ«ما» العاملة وآخر المهملة، واشرح الفرق."},{"unit":"ffd320bc-d285-458e-91b3-5eca91760e2c","n":5,"title":"مئذنة البوح","passage":"لا يثبت عنوان «مئذنة البوح» نوع الصورة أو المتكلم أو المناسبة. مثال مستقل يصف كاتب برجًا مرتفعًا يذكّره بصوت المدينة؛ يسمح بتحليل المكان والرمز دون أن يمثل القصيدة أو يؤلف أبياتًا لصاحبها.","question":"ما الذي يثبت دلالة الرمز في قصيدة؟","correct":"شاهد من النص وسياقه","wrong":["اسم العنوان وحده","خيال القارئ دون دليل","نسبة بيت غير موجود"],"practice":"حدد في القصيدة الموثقة صورة وقرينة على الرمز، ثم قارنها بنص من إنشائك."},{"unit":"ffd320bc-d285-458e-91b3-5eca91760e2c","n":6,"title":"الممنوع من الصرف","passage":"قد يُمنع بعض الأسماء من التنوين والجر بالكسرة لعلة صرفية مثل العلمية ووزن الفعل في اسم «أحمد»، مع استثناءات عند التعريف والإضافة. ندرس الاسم في جملة مضبوطة ولا نعمم الحكم على كل اسم علم.","question":"أي اسم غالبًا ممنوع من الصرف للعِلّة المذكورة؟","correct":"أحمد","wrong":["محمد","خالد","سعيد"],"practice":"اكتب أربعة أسماء ممنوعة من الصرف مع علتها وحالات جرها."},{"unit":"ffd320bc-d285-458e-91b3-5eca91760e2c","n":7,"title":"عند النجاشي","passage":"يحتاج عنوان «عند النجاشي» الرجوع إلى الرواية الصحيحة قبل نسبة كلام إلى شخصية تاريخية أو ربطه بنص ديني. مثال من إنشاء ضاديوم يصور وفدًا يعرض طلبًا بأدلة أمام مسؤول مع احترام المخاطب، لا يروي واقعة النجاشي.","question":"ما الذي يضمن أمانة تحليل حوار تاريخي؟","correct":"نص موثق وسياق محدد","wrong":["إضافة أقوال مختلقة","قراءة العنوان فقط","تغيير اسم المتحدث"],"practice":"وثق حدثًا أو حوارًا من نص مقرر موثوق ثم حلل أسلوب الإقناع دون اختراع الرواية."},{"unit":"ffd320bc-d285-458e-91b3-5eca91760e2c","n":8,"title":"أقسام التشبيه","passage":"التشبيه المرسل يذكر أداته، مثل «الصديق كالنجم في الإرشاد»، والتشبيه المؤكد تحذف أداته في تركيب مناسب. وقد يذكر وجه الشبه أو يحذف، فيختلف التقسيم بحسب العنصر المدروس.","question":"ما نوع «الصديق كالنجم» من حيث ذكر الأداة؟","correct":"تشبيه مرسل","wrong":["استعارة مكنية","طباق","مجاز مرسل"],"practice":"صنف أربعة تشبيهات بحسب ذكر الأداة ووجه الشبه مع بيان أركانها."},{"unit":"ffd320bc-d285-458e-91b3-5eca91760e2c","n":9,"title":"انتظار","passage":"تستلزم قراءة نص «انتظار» معرفة النص الحقيقي وموقع عاطفة المتكلم وتدرج الزمن، ولا يمكن تحديد أحداثه من العنوان. في مثال أصلي ينتظر طالب نتيجة مشروع، ويحوّل القلق إلى مراجعة خطة جديدة؛ يوضح فكرة الانتظار فقط.","question":"ما المهارة التي تساعد على تحليل زمن الانتظار في النص؟","correct":"تتبع الأفعال وقرائن الزمن","wrong":["تخمين خاتمة مجهولة","اختلاق بيت","إلغاء السرد"],"practice":"استخرج من نص مقرر علامتين على مرور الزمن وناقش أثرهما الوجداني."},{"unit":"ffd320bc-d285-458e-91b3-5eca91760e2c","n":10,"title":"البحر الوافر","passage":"في الصورة التامة الشائعة للوافر تتتابع «مفاعلتن مفاعلتن فعولن» في كل شطر وفق أحكام التغيير العروضي. لا يصح تحديد الوزن من القافية وحدها؛ يفحص الشطر بعد كتابته بحسب النطق.","question":"ما التفعيلة الأولى للوافر التام؟","correct":"مفاعلتن","wrong":["متفاعلن","مستفعلن","فاعلاتن"],"practice":"اختر بيتًا موثقًا على الوافر، وقطّعه مع تعليل صورة تفعيلة واحدة."},{"unit":"ffd320bc-d285-458e-91b3-5eca91760e2c","n":11,"title":"مهارة كتابة تقرير","passage":"يتكون التقرير من عنوان وغاية وإجراءات ونتائج ومصادر أو قيود، ويختلف عن الإعلان في ضرورة وضوح التوثيق. في تدريب مستقل يكتب فريق عن مراجعة ترتيب المكتبة ويسجل ما فُعل وما يحتاج متابعة.","question":"ما الجزء الذي يذكر العمل المنفذ في التقرير؟","correct":"الإجراءات","wrong":["عنوان بلا مضمون","توقيع عشوائي","فقرة مدح فقط"],"practice":"اكتب تقريرًا عن نشاط مدرسي مع نتيجة محددة وملاحظة وحدود الدليل."},{"unit":"e6d76fda-d594-4824-89d5-284552e6c693","n":1,"title":"تطور الطب","passage":"تحتاج قراءة تاريخ الطب إلى توثيق تطور الأفكار والأدوات بحسب العصور، ولا تعني صحة بعض الملاحظات القديمة أن جميع علاجاتها صالحة اليوم. في مثال مستقل يقارن متعلم وصفًا تاريخيًا بمعلومات علمية حديثة من مرجع معتمد، دون تقديم استشارة طبية.","question":"ما الأسلوب المناسب لتقييم معلومة طبية تاريخية؟","correct":"مقارنتها بمصدر علمي حديث موثوق","wrong":["قبولها دون تحقق","اختلاق نتائج","رفض تاريخ العلم كله"],"practice":"اكتب فقرة تشرح تغير وسيلة طبية موثقة بين زمنين مع ذكر حدود المعرفة."},{"unit":"e6d76fda-d594-4824-89d5-284552e6c693","n":2,"title":"جملة صلة الموصول","passage":"تأتي جملة الصلة بعد الاسم الموصول لتوضح المقصود، مثل «جاء الطالبُ الذي فازَ»؛ «فاز» فعل في جملة صلة الموصول تتعلق بالاسم «الذي». تحتاج الصلة رابطًا وفق الضوابط النحوية ولا تستقل عن مرجعها.","question":"ما الاسم الموصول في «الطالب الذي فاز»؟","correct":"الذي","wrong":["الطالب","فاز","جاء"],"practice":"اكتب أربع جمل بأسماء موصولة واستخرج جملة الصلة والرابط."},{"unit":"e6d76fda-d594-4824-89d5-284552e6c693","n":3,"title":"الاتصال السمعي البصري","passage":"يجمع الاتصال السمعي البصري بين الصوت والصورة، ويؤثر اختيار اللقطة والنبرة في فهم الرسالة؛ لا يكفي جمال العرض لإثبات صحة المعلومة. في مثال مستقل يصمم فريق مقطعًا عن المكتبة مع عنوان واضح ومصدر للمعلومات.","question":"ما الذي يعزز مصداقية المقطع التعليمي؟","correct":"توثيق المعلومات المعروضة","wrong":["زيادة المؤثرات وحدها","إخفاء المصدر","تبديل الأرقام"],"practice":"خطط مقطعًا قصيرًا من ثلاث لقطات مع نص واضح ومصادر وصوت مناسب."},{"unit":"e6d76fda-d594-4824-89d5-284552e6c693","n":4,"title":"الجناس","passage":"الجناس تشابه كلمتين في اللفظ مع اختلاف المعنى، وقد يكون تامًا أو ناقصًا بحسب التطابق. لا نقرر وجود الجناس لمجرد تشابه المعنى دون تقارب الأصوات، ويحتاج التحليل مثالًا لغويًا صحيحًا.","question":"ما العلاقة الأساسية في الجناس؟","correct":"تشابه اللفظ واختلاف المعنى","wrong":["تضاد المعنى فقط","تكرار الصورة نفسها","تطابق الدلالة تمامًا"],"practice":"ابحث عن مثال بلاغي صحيح للجناس واشرح معنى اللفظين ونوع التشابه."},{"unit":"e6d76fda-d594-4824-89d5-284552e6c693","n":5,"title":"سجايا النبي صلى الله عليه وسلم","passage":"لا يجوز إضافة حديث أو قول إلى النبي صلى الله عليه وسلم دون مصدر موثوق. يركز تدريب ضاديوم المستقل على كيفية التحقق من السيرة والحديث قبل الاستشهاد، من خلال مثال معاصر عن الصدق وحسن المعاملة لا يُعرض باعتباره رواية تاريخية.","question":"ما الواجب قبل نقل حديث في هذا الدرس؟","correct":"التحقق من النص والمصدر ودرجة الثبوت","wrong":["اختلاق متن ملائم","الاستناد إلى صورة مجهولة","نقل قول بلا مرجع"],"practice":"اختر حديثًا صحيحًا من مرجع معتمد مع المعلم، ثم ناقش قيمة لغوية دون تحريف المتن."},{"unit":"e6d76fda-d594-4824-89d5-284552e6c693","n":6,"title":"الطباق والمقابلة","passage":"الطباق جمع لفظين متقابلين في المعنى مثل «الليل والنهار»، والمقابلة تتضمن ذكر معنيين أو أكثر ثم ما يقابلها على الترتيب في تركيب بلاغي مناسب. ليست كل جملة فيها كلمتان مختلفتان مثالًا طباقيًا.","question":"أي زوج يصلح للطباق؟","correct":"الليل والنهار","wrong":["الكتاب والقلم","الباب والنافذة","المدرسة والمكتبة"],"practice":"أنشئ مثالين للطباق ثم ابحث عن مقابلة صحيحة واشرح ترتيب المعاني."},{"unit":"e6d76fda-d594-4824-89d5-284552e6c693","n":7,"title":"في الطريق إلى الإسكندرية","passage":"عنوان «في الطريق إلى الإسكندرية» لا يثبت مكان الأحداث أو أسماء المتكلمين خارج ما يرد في النص. في سفر تخيلي مستقل يراجع مسافر خريطته ويسأل عن الطريق، وهو تمرين على السرد والوصف دون نسبة فقرة للمؤلف المقرر.","question":"ما الدليل على وجهة الرحلة في أي نص سردي؟","correct":"عبارة صريحة من النص وسياقها","wrong":["الاعتماد على العنوان وحده","اختراع محطة سفر","التخمين من صورة"],"practice":"استخرج من النص الأصلي حدثين متتابعين ووصفًا للمكان مع توثيق الشاهد."},{"unit":"e6d76fda-d594-4824-89d5-284552e6c693","n":8,"title":"البحر المتقارب","passage":"تقوم صيغة البحر المتقارب التام الأصلية على تكرار «فعولن» أربع مرات في كل شطر قبل الزحافات والعلل، ويعتمد التقطيع على المنطوق والحركات لا رسم الكلمة فقط.","question":"ما التفعيلة الأساسية للمتقارب؟","correct":"فعولن","wrong":["متفاعلن","مفاعلتن","مستفعلن"],"practice":"قطّع شطرًا موثقًا من البحر المتقارب واشرح أثر حرف مد أو شدة."},{"unit":"e6d76fda-d594-4824-89d5-284552e6c693","n":9,"title":"بين البدو والحضر","passage":"لا يصح التعميم بأن جميع أهل البادية أو المدينة يعيشون بالطريقة نفسها؛ يحتاج وصف الاختلاف إلى زمان ومكان وشاهد. نموذج مستقل يزور فيه طالب مكانين، ويلاحظ اختلاف بعض وسائل النقل مع التشابه في احتياجات الناس الأساسية.","question":"ما الذي يجعل المقارنة بين بيئتين منصفة؟","correct":"ذكر سياق محدد وتجنب التعميم","wrong":["القول إن الجميع متماثلون","الاعتماد على صورة واحدة","حذف ظروف المكان"],"practice":"اكتب مقارنة متوازنة بين بيئتين مع تفاصيل يمكن التحقق منها وحدود الاستنتاج."},{"unit":"e6d76fda-d594-4824-89d5-284552e6c693","n":10,"title":"مهارة توسيع فكرة","passage":"لتوسيع فكرة «المكتبة نافذة للمعرفة» يوضح الكاتب المعنى ثم يقدم مثالًا وتفسيرًا ونتيجة، دون تكرار الجملة نفسها. يمكن دعم الفقرة بقصة قصيرة أو مقارنة بشرط اتصالها بالأطروحة.","question":"ما الذي يجعل توسيع الفكرة مفيدًا؟","correct":"إضافة تفسير ومثال ونتيجة مترابطة","wrong":["تكرار الجملة حرفيًا","تغيير الموضوع","إطالة بلا معنى"],"practice":"وسّع فكرة من سطر واحد إلى فقرة من ست جمل تتضمن دليلًا وتفسيرًا."},{"unit":"a5087bd6-2b3a-4704-b6e7-39f82a2e77ee","n":1,"title":"تزايد النمو السكاني","passage":"يتطلب تناول النمو السكاني أرقامًا مؤرخة من مصدر إحصائي معتمد وتفسير فرق العدد عن معدل الزيادة، ولا تساوي قصة أسرة صغيرة إحصاءً وطنيًا. مثال مستقل يناقش فريق احتياجات حي متغير قبل بناء خطة لخدماته.","question":"ما المصدر اللازم لعرض معدل نمو سكاني؟","correct":"بيانات إحصائية مؤرخة وموثوقة","wrong":["تخمين شخصي","صورة بلا مصدر","حوار خيالي"],"practice":"اكتب فقرة تناقش أثر تغير السكان على خدمة عامة مع التمييز بين الدليل والاحتمال."},{"unit":"a5087bd6-2b3a-4704-b6e7-39f82a2e77ee","n":2,"title":"الجملة الواقعة فاعلًا أو نائب فاعل","passage":"في بعض التراكيب النحوية المتقدمة يُدرس المصدر المؤول من «أنْ» والفعل في مواقع إعرابية يمكن أن يؤدي فيها وظيفة الاسم، بحسب تركيب الجملة؛ مثل «يسرّني أنْ تنجحَ» حيث يُحلل المصدر المؤول على أنه فاعل مؤخر في وجه معروف. لا نعمم على كل جملة فعلية.","question":"ما الذي يساعد على تحليل المصدر المؤول في «يسرّني أن تنجح»؟","correct":"تحديد موقعه من العامل النحوي","wrong":["عد الحروف فقط","حذف العامل","الاستناد إلى الترقيم"],"practice":"راجع مثالين من مرجع نحوي موثوق للجملة أو المصدر المؤول في مواقع الرفع، مع إعراب وتحفظات."},{"unit":"a5087bd6-2b3a-4704-b6e7-39f82a2e77ee","n":3,"title":"وسائط التواصل الاجتماعي","passage":"يمكن للمنصات الرقمية دعم النقاش والتعلم، لكنها قد تنقل معلومة غير صحيحة؛ في مثال مستقل يرفض طالب مشاركة خبر حتى يجد مصدره وتاريخه. يتطلب التقييم التحقق من الخصوصية وهوية الناشر والأدلة.","question":"ما التصرف السليم قبل إعادة نشر خبر؟","correct":"مراجعة المصدر والوقت والدليل","wrong":["الاعتماد على عدد الإعجابات","نشره فورًا","إخفاء هوية المصدر"],"practice":"صمم بطاقة تحقق من معلومة متداولة بثلاث خطوات وشرح موجز."},{"unit":"a5087bd6-2b3a-4704-b6e7-39f82a2e77ee","n":4,"title":"الجملة الواقعة مفعولًا به","passage":"قد تأتي جملة في موقع المفعول به في أبواب نحوية محددة، مثل جملة مقول القول «قال المعلم: الدرسُ مفيدٌ»؛ ويحتاج التحليل بيان الفعل الذي تعلق به القول والتمييز بين لفظ الجملة وموقعها الإعرابي.","question":"ما وظيفة «الدرس مفيد» في المثال بوصفها كلامًا منقولًا؟","correct":"جملة مقول القول في موضع مفعول به","wrong":["فاعل «قال»","حرف جر","ظرف زمان"],"practice":"حلل مثالًا صحيحًا لمقول القول من مرجع نحوي، وبيّن موضع الجملة ودلالة السياق."},{"unit":"a5087bd6-2b3a-4704-b6e7-39f82a2e77ee","n":5,"title":"حنين إلى الربوع","passage":"يتطلب تحليل نص «حنين إلى الربوع» أبياته المقررة قبل تحديد المخاطب أو صور المكان؛ مثال مستقل يرى فيه مسافر آثار منزله القديم فتعود إليه الذكرى، وهو نثر من إنشاء ضاديوم لا بيت من القصيدة.","question":"ما العاطفة في المثال المستقل؟","correct":"الحنين إلى المكان","wrong":["اللامبالاة","السخرية","المنافسة"],"practice":"استخرج صورة مكانية صحيحة من النص الموثق واشرح أثرها في العاطفة."},{"unit":"a5087bd6-2b3a-4704-b6e7-39f82a2e77ee","n":6,"title":"المضاف إليه ما قبله","passage":"تتعلق الإضافة باسمين مثل «كتابُ الطالبِ»، حيث «كتابُ» مضاف و«الطالبِ» مضاف إليه مجرور. لا تكون كل كلمة تأتي بعد اسم مضافًا إليه؛ يلزم تركيب الإضافة والمعنى والعلامة الإعرابية.","question":"ما المضاف إليه في «كتاب الطالب»؟","correct":"الطالبِ","wrong":["كتابُ","الواو","إلى"],"practice":"اكتب خمس إضافات وحدد المضاف والمضاف إليه وعلامة الجر."},{"unit":"a5087bd6-2b3a-4704-b6e7-39f82a2e77ee","n":7,"title":"أزمة اقتصادية","passage":"فهم نص عن أزمة اقتصادية يحتاج تمييز أسباب مزعومة عن نتائج مثبتة وإحصاءات موثوقة مع سياقها الزمني. في مثال مستقل يعيد فريق مدرسي ترتيب ميزانية رحلة بعدما ارتفعت بعض التكاليف؛ لا يمثل حالة اقتصادية تاريخية.","question":"ما التصرف الأفضل لتقييم دعوى اقتصادية؟","correct":"مراجعة الأرقام ومصادرها والسياق","wrong":["تخمين الأسعار","اعتبار حالة واحدة عامة","حذف تاريخ البيانات"],"practice":"اكتب تقريرًا قصيرًا يميز وصف المشكلة من فرضيات الأسباب والحلول."},{"unit":"a5087bd6-2b3a-4704-b6e7-39f82a2e77ee","n":8,"title":"الحقيقة والمجاز","passage":"في «أضاء المصباحُ الغرفةَ» إضاءة حقيقية في السياق، وفي «أضاء العلمُ طريقَه» إضاءة مجازية لأن العلم ليس مصباحًا ماديًا. يتحدد التحليل من العلاقة بين اللفظ والسياق لا من الكلمة وحدها.","question":"أي جملة تتضمن إضاءة مجازية؟","correct":"أضاء العلم طريقه","wrong":["أضاء المصباح الغرفة","أشعلت الأضواء","انطفأ المصباح"],"practice":"اكتب مثالين للحقيقة وآخرين للمجاز، واشرح القرينة المانعة من المعنى الحقيقي."},{"unit":"a5087bd6-2b3a-4704-b6e7-39f82a2e77ee","n":9,"title":"التعاون (أتويزة)","passage":"يعرض مفهوم «التويزة» في الثقافة المغاربية أنماطًا من التعاون الجماعي في أعمال مشتركة، لكن تفاصيل الممارسة تختلف بحسب المكان والزمان. في مثال مستقل يتشارك جيران تنظيف مساحة عامة وينظمون الأدوات برضا الجميع.","question":"ما العنصر الأساسي في التعاون الوارد بالمثال؟","correct":"تقاسم العمل لأجل منفعة مشتركة","wrong":["إجبار الآخرين","حجب المعلومات","إخفاء الأدوات"],"practice":"وثق مثالًا اجتماعيًا صحيحًا للتويزة من مرجع ثقافي، ثم قارنه بمبادرة معاصرة."},{"unit":"a5087bd6-2b3a-4704-b6e7-39f82a2e77ee","n":10,"title":"الاستعارة التصريحية والمكنية","passage":"الاستعارة التصريحية يذكر فيها المشبه به ويحذف المشبه مع قرينة مناسبة، والمكنية يُذكر فيها المشبه ويُحذف المشبه به مع ما يدل عليه؛ في «ابتسم الصباح» تُشخص ظاهرة الصباح على نحو مكني.","question":"ما نوع الاستعارة في «ابتسم الصباح»؟","correct":"استعارة مكنية","wrong":["جناس","طباق","توكيد لفظي"],"practice":"اكتب مثالين صحيحين للاستعارة بنوعيها، وبيّن القرينة وأثر الصورة."},{"unit":"a5087bd6-2b3a-4704-b6e7-39f82a2e77ee","n":11,"title":"مهارة إنتاج نص حكائي","passage":"يبنى السرد على شخصية وغاية وعائق وتسلسل زمني ثم تغير ونتيجة؛ مثال مستقل يضل طالب الطريق إلى نشاط مدرسي ثم يسأل عن عنوان صحيح فيصل في الوقت المناسب. لا يحتاج النص إلى حكايات تاريخية منسوبة.","question":"ما الذي يمثل العقدة في القصة التدريبية؟","correct":"ضياع الطريق إلى النشاط","wrong":["الوصول بعد السؤال","وجود طالب","انتهاء الحدث"],"practice":"اكتب قصة قصيرة من خمس فقرات تتضمن بداية وعقدة ومحاولة حل وخاتمة."}]'::jsonb)
 AS x(unit uuid,n integer,title text,passage text,question text,correct text,wrong text[],practice text)
 LOOP
  SELECT l.id,l.content INTO STRICT target_id,prior
  FROM public.lessons l JOIN public.units u ON u.id=l.unit_id
  JOIN public.grades g ON g.id=u.grade_id
  JOIN public.curricula c ON c.id=g.curriculum_id
  JOIN public.countries co ON co.id=c.country_id
  WHERE co.code='MR' AND c.id='63caf345-c342-48eb-9582-fdbf0a61ef7f'::uuid
    AND g.grade_number=10 AND u.semester IS NULL AND u.id=r.unit
    AND l.sort_order=r.n AND l.title=r.title AND l.status='published'
  FOR UPDATE OF l;

  SELECT count(*) INTO hasprogress FROM public.student_lesson_progress WHERE lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'MR_G10_HAS_PROGRESS_%',r.title; END IF;
  SELECT count(*) INTO hasprogress FROM public.lesson_activity_attempts att
    JOIN public.lesson_activities a ON a.id=att.activity_id WHERE a.lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'MR_G10_HAS_ATTEMPTS_%',r.title; END IF;
  IF char_length(coalesce(prior,''))>=350 THEN RAISE EXCEPTION 'MR_G10_ALREADY_CONTENT_%',r.title; END IF;
  SELECT count(*) INTO nact FROM public.lesson_activities
    WHERE lesson_id=target_id AND content->>'origin'='DADYOOM_MR_G10_OFFICIAL' AND answer='{}'::jsonb;
  IF nact<>3 THEN RAISE EXCEPTION 'MR_G10_EXPECTED_3_PLACEHOLDERS_%',r.title; END IF;

  UPDATE public.lessons SET
    content='ضاديوم — إثراء تعليمي أصلي للسنة الرابعة الإعدادية في موريتانيا. هذا ليس نص الكتاب المعتمد ولا تأكيدًا لمطابقة جميع الفصول؛ الاسم مستورد ويلزم تحقق وزاري.'
    ||E'\n\n'||'عنوان الدرس: '||r.title
    ||E'\n\n'||'هدف التعلم: أن يشرح المتعلم فكرة أو قاعدة من المجال، ويحلل قرينة أو شاهدًا صحيح النسبة، ويكتب استجابة جديدة تستند إلى دليل.'
    ||E'\n\n'||'شرح وتطبيق أصلي: '||r.passage
    ||E'\n\n'||'سؤال فهم: '||r.question
    ||E'\n\n'||'تطبيق كتابي مستقل: '||r.practice
    ||E'\n\n'||'التمايز: دعم بقائمة مفردات وخطوات تحليل أساسية، ومستوى متوسط يبرر الاختيار، ومستوى متقدم يقارن بين تفسيرين أو يختبر دقة المصدر. يتولى المعلم مراجعة مهام الكتابة.'
    ||E'\n\n'||'تحذير المصدر: لا تُنسب أمثلة ضاديوم إلى شاعر أو مؤرخ أو نص ديني؛ راجع المصدر المعتمد أولًا.'
    ||E'\n\n'||'المحتوى السابق المحفوظ: '||coalesce(prior,''),
    updated_at=now() WHERE id=target_id;

  UPDATE public.lesson_activities SET
    prompt='اقرأ النص التدريبي المستقل، واستخرج منه الفكرة أو الشاهد الذي تستند إليه الإجابة.',
    content=content||jsonb_build_object('origin','DADYOOM_MR_G10_43_ORIGINAL_20261009','previousOrigin','DADYOOM_MR_G10_OFFICIAL',
      'text',r.passage,'notOfficialBook',true,'sourceVerification','pending')
    WHERE lesson_id=target_id AND activity_type='reading'
      AND content->>'origin'='DADYOOM_MR_G10_OFFICIAL' AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.question,
    content=content||jsonb_build_object('origin','DADYOOM_MR_G10_43_ORIGINAL_20261009','previousOrigin','DADYOOM_MR_G10_OFFICIAL',
       'text',r.question,'notOfficialBook',true,'sourceVerification','pending',
       'options',CASE (r.n%4)
       WHEN 0 THEN jsonb_build_array(r.correct,r.wrong[1],r.wrong[2],r.wrong[3])
       WHEN 1 THEN jsonb_build_array(r.wrong[1],r.correct,r.wrong[2],r.wrong[3])
       WHEN 2 THEN jsonb_build_array(r.wrong[1],r.wrong[2],r.correct,r.wrong[3])
       ELSE jsonb_build_array(r.wrong[1],r.wrong[2],r.wrong[3],r.correct) END),
    answer=jsonb_build_object('correct',r.correct)
    WHERE lesson_id=target_id AND activity_type='multiple_choice'
      AND content->>'origin'='DADYOOM_MR_G10_OFFICIAL' AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.practice,
    content=content||jsonb_build_object('origin','DADYOOM_MR_G10_43_ORIGINAL_20261009','previousOrigin','DADYOOM_MR_G10_OFFICIAL',
     'text',r.practice,'notOfficialBook',true,'sourceVerification','pending',
     'humanReviewRequired',true)
    WHERE lesson_id=target_id AND activity_type='writing'
      AND content->>'origin'='DADYOOM_MR_G10_OFFICIAL' AND answer='{}'::jsonb;

  SELECT count(*) INTO nact FROM public.lesson_activities
   WHERE lesson_id=target_id AND content->>'origin'='DADYOOM_MR_G10_43_ORIGINAL_20261009';
  IF nact<>3 THEN RAISE EXCEPTION 'MR_G10_ACTIVITY_UPDATE_FAILED_%',r.title; END IF;
 END LOOP;
END $dadyoom$;